  const runKey = `${process.env.GITHUB_RUN_ID || 'local'}:${process.env.GITHUB_RUN_ATTEMPT || '1'}`;
  const staleRunSeats = Object.values(boardLedger?.seats || {})
    .filter(s => s.status === 'reserved' && s.claim_receipt?.run_key && s.claim_receipt.run_key !== runKey);
  if (staleRunSeats.length) {
    throw Error(`daily_reservation_run_key_mismatch:${staleRunSeats.map(s => s.agent).join(',')}`);
